class Queue:
    def __init__(self):
        self.que = []
    def isEmpty(self):
        return len(self.que) == 0
    def enqueue(self, data):
        self.que.append(data)
    def dequeue(self):
        if not self.isEmpty():
            return self.que.pop(0)
    def peek(self):
        if not self.isEmpty():
            return self.que[0]

q = Queue()
for ch in ['A', 'B', 'C']:
    q.enqueue(ch)
print(q.peek())
print(q.dequeue())
print(q.dequeue())
print(q.isEmpty())

line = ['민수', '지아', '하준', '서연', '도윤']
turn = 0
while line:
    turn += 1
    riders = []
    for _ in range(2):
        if line:
            riders.append(line.pop(0))
    print(f'{turn}회차 탑승:', ', '.join(riders))
